/* Customer business code split by dependency; shared records and existing handlers stay compatible. */
'use strict';
function flowStage(c=current()){return c.step>=8?4:c.planReady?3:c.step>=4?2:1}
function flowStatus(c){if(c.review&&['pending','finance','rejected'].includes(c.review.status))return apStatus(c,'correction');if(c.status==='已终止')return '已终止';if(c.status==='已完成')return '已完成';if(c.paused)return '待核查';if(c.resultData)return '待确认结果';if(c.status==='执行失败')return '执行失败';if(c.status==='执行中')return '执行中';return c.approval?'待执行':'待审核'}
function flowStatusBadge(c){let s=flowStatus(c);return badge(s,s==='已完成'?'green':s.includes('补充')||s==='待核查'?'orange':flowStage(c)===4?'purple':'blue')}
function flowOpen(id){flowTab='manual';go('ticket',id)}
function mrCorrectionSummary(c){if(c.businessVersion===5)return '已完成'+({split:'客户分离与业务归属',partial:'选定业务',performance:'员工业绩',profile:'基本资料'}[c.businessPlan.scope]||'本次')+'纠正，客户与员工调整明细可追溯。';if(c.pendingItems?.length)return '已执行本次明确的数据归属；仍有 '+c.pendingItems.length+' 条待定记录保留主档案，可继续补充归属。';let r=state.mergeRecords?.find(r=>r.id===c.merge);return r?.pair.length>2&&mrStatus(r)==='部分已纠错'?'本次原档案已完成纠错；该次合并还有其他原档案，可继续按需核对。':'主档案与独立档案已归位，本次纠错已完成。'}
function mrCorrection(r){return state.cases.find(c=>c.merge===r.id&&c.status!=='已完成')||state.cases.find(c=>c.merge===r.id&&c.status==='已完成')}
function mrStatus(r){if(r.revoked)return '已撤销';let cases=state.cases.filter(c=>c.merge===r.id),active=cases.find(c=>!['已完成','已终止'].includes(c.status));if(active)return '纠错中';if(cases.some(c=>c.pendingItems?.length))return '部分已纠错';if(cases.some(c=>c.businessPlan?.targetDefinitionVersion))return '部分已纠错';if(cases.length){let children=r.pair.filter(c=>c.id!==r.plan.mainId);return children.every(child=>cases.some(c=>c.sub===child.id&&c.status==='已完成'&&(c.businessVersion!==5||c.businessPlan.scope==='split')))?'已纠错':'部分已纠错'}if(r.archived||mrTime(r.retainUntil)<Date.now())return '快照已归档';if(mrTime(r.coolingUntil)>Date.now())return '冷静期中';return '已合并'}
function mrBadge(s){return badge(s,['已合并','已执行','已通过','已纠错'].includes(s)?'green':['待审核','冷静期中','纠错中','部分已纠错','执行失败'].includes(s)?'orange':['已驳回','已撤销'].includes(s)?'red':'')}
function maIdentityRows(pair){let rows=new Map();for(let c of pair){for(let [type,values] of [['phone',[c.phone,c.oldPhone,...(c.phones||[])]],['union',[c.unionId,...(c.unionIds||[])]],['external',[c.externalId,...(c.externalIds||[])] ]])for(let value of values.filter(Boolean)){let key=type+':'+value;if(!rows.has(key))rows.set(key,{type,value,sources:[]});let row=rows.get(key);if(!row.sources.some(x=>x.id===c.id))row.sources.push({id:c.id,name:c.name})}}return [...rows.values()]}
function maOrderInfo(c,o){return {name:o.name||o.projectName||(o.items||[]).map(x=>x.name).filter(Boolean).join('、')||'未记录项目',store:o.store||o.receptionStore||'',bookingBy:o.bookingBy||o.appointmentBy||o.scheduler||'',receiver:o.receiver||o.receptionist||o.receptionEmployee||'',created:o.createdAt||o.created||o.at||'',appointment:o.appointmentAt||o.scheduledAt||'',arrived:o.arrivedAt||o.checkinAt||'',paid:o.paidAt||''}}
function mrLogs(r){return contentModule('操作记录',body(`<div class="mr-timeline">${(r.logs||[]).map(l=>`<div><div class="tiny muted">${l.at} · ${esc(l.by)}</div><p>${esc(l.content)}</p></div>`).join('')}</div>`))}
function mrUndoAsk(id){let r=state.mergeRecords.find(x=>x.id===id);if(!r||r.revoked)return;if(mrTime(r.coolingUntil)<=Date.now()||r.followUp||mrCorrection(r)){toast('该记录不满足冷静期撤销条件，请查看详情');return}modal('撤销本次合并',`<p>将基于 ${r.id} 的合并前快照恢复全部 ${r.pair.length} 份档案和迁移数据。</p><p class="small muted" style="margin-top:12px">原合并记录保留并标记为“已撤销”，无需审批。</p>`,btn('取消','closeModal()')+btn('确认撤销',`mrUndo(${mrQuote(id)})`,'danger'))}
function mrUndo(id){if(!PCCustomerStorage.locked)return customerWrite(()=>mrUndo(...arguments));let r=state.mergeRecords.find(x=>x.id===id);if(!r||r.revoked||mrTime(r.coolingUntil)<=Date.now()||r.followUp||mrCorrection(r))return;for(let c of r.snapshot.before){let idx=state.mergeCustomers.findIndex(x=>x.id===c.id);if(idx>=0)state.mergeCustomers[idx]=clone(c)}r.revoked=true;r.revokedAt=now();mrEvent(r,'冷静期撤销：已依据快照恢复主、子档案与数据关系');let app=state.mergeApplications.find(a=>a.id===r.applicationId);if(app){app.status='已撤销';mrEvent(app,'执行后的合并在冷静期内被撤销，关联记录 '+id)}persist();closeModal();render();toast('合并已撤销，全部参与档案已恢复')}
function mrGoCorrection(id){let r=state.mergeRecords.find(x=>x.id===id);if(!r)return;if(r.pair.length>2){mrStartCorrection(id);return}let c=mrCorrection(r);if(!c)return;mrTask=null;closeModal();flowOpen(c.id)}
function mrStartCorrection(id,childId){let r=state.mergeRecords.find(x=>x.id===id);if(!r||r.revoked)return;if(mrTime(r.coolingUntil)>Date.now()){toast('该记录仍在冷静期内，可先查看撤销入口');return}if(r.archived||mrTime(r.retainUntil)<Date.now()){mrArchived(id);return}let source=cxSources().find(c=>c.merge===id);if(!source)return toast('未找到该合并记录的纠错来源');newForm={reason:'合并了不同人',description:'',expect:'',evidence:[],sourceId:source.id};mrTask=null;closeModal();cxOpenApplication();toast('已带入整组合并记录，请先明确本次需要分离的客户')}
function mgAppStatus(a){return ({'待审核':'待审核','已通过':'系统执行中','已执行':'已合并','确认不合并':'已排除','已驳回':'已结束','已撤回':'已结束','已撤销':'已结束','执行失败':'执行失败'})[a.status]||a.status}
function mgBadge(s){return badge(s,s==='已合并'?'green':s==='执行失败'?'red':['待核实','待执行'].includes(s)?'orange':'')}
function mrArchived(id){modal('归档快照 · 手工调账记录',kv({'原合并记录':esc(id),'处理方式':'手工梳理数据归属，保留原流水及完整调账记录'})+((state.manualCorrectionRecords||[]).filter(x=>x.merge===id).length?contentModule('已有手工调账记录',table(['时间 / 操作人','原因','影响范围','明细与依据'],state.manualCorrectionRecords.filter(x=>x.merge===id).map(x=>[esc(x.at)+'<div>'+esc(x.by)+'</div>',esc(x.reason),esc(x.scope),esc(x.detail)]))):'')+'<div class="form-stack" style="margin-top:18px">'+field('调账原因（选填）','<textarea id="cxArchiveReason"></textarea>')+field('影响范围与归属方案（选填）','<textarea id="cxArchiveScope"></textarea>')+field('调整明细及依据（选填）','<textarea id="cxArchiveDetail"></textarea>')+'</div>',btn('关闭','closeModal()')+btn('保存手工调账记录',`cxArchiveSave(${mrQuote(id)})`,'primary'),true)}
function cxArchiveSave(id){if(!PCCustomerStorage.locked)return customerWrite(()=>cxArchiveSave(...arguments));state.manualCorrectionRecords||=[];state.manualCorrectionRecords.push({id:'MC-'+now().slice(0,10).replaceAll('-','')+'-'+(state.manualCorrectionRecords.length+1),merge:id,reason:$('#cxArchiveReason').value||'示例：快照归档后纠错',scope:$('#cxArchiveScope').value||'示例：按业务凭证梳理',detail:$('#cxArchiveDetail').value||'示例：记录调整依据与明细',at:now(),by:'张三 · OP-001'});persist();closeModal();toast('手工调账记录已保存')}
function pcCustomerModal(){let c=pcCustomers().find(c=>c.id===pcModalCustomer?.id);if(!c)return;modal('客户档案 · '+c.name,pcCustomerTabs(c,pcModalCustomer.tab,true)+pcCustomerContent(c,pcModalCustomer.tab),btn('关闭','closeModal()'),true)}
function pcCustomerTab(tab,nested=false){if(nested){pcModalCustomer.tab=tab;pcCustomerModal()}else{mrTask.tab=tab;render()}}
function pcCustomerTabs(c,tab,nested=false){return `<div class="merge-rule-tabs" role="tablist" aria-label="客户档案分类">${[['overview','基本信息'],['business','业务记录'],['history','合并历史']].map(([k,t],i)=>`<button class="merge-rule-tab ${tab===k?'active':''}" role="tab" aria-selected="${tab===k}" tabindex="${tab===k?'0':'-1'}" onclick="pcCustomerTab('${k}',${nested})" onkeydown="pcLocalTabKey(event,${i})">${t}</button>`).join('')}</div>`}
function pcLocalTabKey(e,i){if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let tabs=[...e.target.parentElement.querySelectorAll('[role=tab]')],n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].click();setTimeout(()=>document.querySelector('[role=tablist][aria-label="客户档案分类"] [aria-selected=true]')?.focus(),0)}
function pcCustomerContent(c,tab){if(tab==='business'&&bpRichProfile(c))return bpCustomerBusiness(c);if(tab==='business')return pcBusinessSections({pair:[c]},'');if(tab==='history')return pcCustomerHistory(c);let main=pcCustomers().find(x=>x.id===c.mergedInto);return contentModule('客户资料',body(kv({'客户编号':esc(c.id),'客户姓名':esc(c.name),'手机号':esc(c.phone||'—'),'备用 / 旧手机号':esc(c.oldPhone||'—'),'所属门店':esc(c.store||'—'),'归属客服':esc(c.consultant||'—'),'客户类型':esc(c.customerType||pcStats(c).customerType),'合并状态':badge(pcCustomerStatus(c)),'主档案':c.mergedInto?`<button class="inline-link" onclick="pcCustomerSwitch(${esc(mrQuote(c.mergedInto))})">${esc(main?.name||'主档案')} · ${esc(c.mergedInto)}</button>`:'当前为独立主档案','纠错来源':c.correctionCaseId?btn(c.correctionCaseId,`pcGoCase(${mrQuote(c.correctionCaseId)})`,'text'):'—','原合并记录':c.merge?btn(c.merge,`pcViewRecord(${mrQuote(c.merge)})`,'text'):'—','当前业务来源':esc(c.sourceCustomerId||c.originalChildId||'—'),'历史参考档案':(c.historicalSourceIds||[]).map(esc).join('、')||'未引用'})))+pcStatsTable([c],'客户统计')+(bpRichProfile(c)?bpCustomerOverview(c):'')}
function pcCustomerSwitch(id){if(pcModalCustomer){pcModalCustomer={id,tab:'overview'};pcCustomerModal()}else pcOpenCustomer(id)}
function pcCustomerHistory(c){let extra=bpCustomerCorrectionHistory(c);let records=state.mergeRecords.filter(r=>r.pair.some(x=>x.id===c.id)).sort((a,b)=>b.time.localeCompare(a.time));return extra+contentModule('历次合并记录',records.length?table(['合并编号 / 时间','参与身份','主档案','其他参与档案','合并方式 / 状态','操作'],records.map(r=>[esc(r.id)+'<div class="tiny muted">'+r.time+'</div>',r.plan.mainId===c.id?'主档案':'被合并档案',esc(r.pair.find(x=>x.id===r.plan.mainId)?.name||r.plan.mainId),r.pair.filter(x=>x.id!==c.id).map(x=>esc(x.name)+' · '+esc(x.id)).join('<br>'),esc(r.method)+'<div>'+mrBadge(mrStatus(r))+'</div>',btn('查看记录 / 快照',`pcViewRecord(${mrQuote(r.id)})`,'text')+pcHistoryActions(r)])):body('<p class="small muted">此档案尚未参与过合并。</p>'))+(c.correctionCaseId?contentModule('纠错来源',body(kv({'纠错工单':btn(c.correctionCaseId,`pcGoCase(${mrQuote(c.correctionCaseId)})`,'text'),'原合并记录':btn(c.merge,`pcViewRecord(${mrQuote(c.merge)})`,'text'),'原子档案':esc(c.originalChildId||'—')}))):'')}
function pcHistoryActions(r){if(mrTask?.kind!=='customer'||pcModalCustomer)return '';let s=mrStatus(r);return s==='冷静期中'&&!r.followUp&&!mrCorrection(r)?btn('撤销',`mrUndoAsk(${mrQuote(r.id)})`,'text'):['已合并','部分已纠错'].includes(s)?btn('发起纠错',`pcCorrection(${mrQuote(r.id)})`,'text'):mrCorrection(r)?btn('纠错工单',`pcCorrection(${mrQuote(r.id)})`,'text'):''}
function pcDrawer(){let c=pcCustomers().find(c=>c.id===mrTask.id);if(!c)return '';return `<div class="merge-drawer-backdrop" onclick="if(event.target===this&&!this.dataset.closing&&!document.querySelector('#modal>[data-overlay-layer]'))mrClose()"><section id="mergeRecordPanel" class="merge-drawer" role="dialog" aria-modal="true" aria-label="客户档案"><header class="merge-drawer-head"><h2>客户档案 · ${esc(c.name)}</h2><button class="icon-btn" aria-label="关闭客户档案" onclick="mrClose()">${icon('close')}</button></header><div class="merge-drawer-body" data-drawer-scroll="merge-record">${pcArchiveView(c,mrTask.tab)}</div><footer class="merge-drawer-foot">${btn('关闭','mrClose()')}</footer></section></div>`}
function pcCorrection(id){pcModalCustomer=null;closeModal();mrTask=null;let r=state.mergeRecords.find(r=>r.id===id);if(!r)return;if(mrCorrection(r))mrGoCorrection(id);else mrStartCorrection(id)}
function pcRecordTabKey(e,i){if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let tabs=[...e.target.parentElement.querySelectorAll('[role=tab]')],n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length,action=tabs[n].getAttribute('onclick');tabs[n].click();setTimeout(()=>[...document.querySelectorAll('[role=tab]')].find(t=>t.getAttribute('onclick')===action)?.focus(),0)}
function pcData(id,ref=''){let r=state.mergeRecords.find(r=>r.id===ref)||state.mergeApplications.find(r=>r.id===ref);return r?.snapshot?.before?.find(c=>c.id===id)||r?.pair.find(c=>c.id===id)||mrTask?.pair?.find(c=>c.id===id)||pcCustomers().find(c=>c.id===id)}
function pcBusinessSections(r,ref=r.id||''){
 let pair=r.pair,whiteRows=pair.flatMap(c=>pcLedger(c).map(x=>[esc(c.name),esc(x.id),esc(x.type),esc(x.orderId||'—'),esc(x.at||'—'),cxSign(pcPaymentAmount(x)),btn('查看',`pcBusinessDetail('white',${mrQuote(c.id)},${mrQuote(x.id)},${mrQuote(ref)})`,'text')]));
 let white=table(['所属档案','流水编号','业务类型','关联订单','发生时间','金额','操作'],whiteRows)+body(pair.map(c=>{let w=pcWalletCheck(c);return `<p class="small">${esc(c.name)}：余额 ${money(w.balance)} / 流水净值 ${w.known?money(w.total):'未保存完整流水'} ${badge(!w.known?'待补充明细':w.ok?'一致':'差异 '+cxSign(w.diff),w.ok?'green':'orange')}</p>`}).join(''));
 let tickets=table(['所属档案','工单编号','类型 / 状态','问题摘要','操作'],pair.flatMap(c=>(c.tickets||[]).map(x=>[esc(c.name),esc(x.id),esc(x.type||'售后')+' / '+esc(x.status||'—'),esc(x.name||x.summary||'—'),btn('查看详情',`pcBusinessDetail('ticket',${mrQuote(c.id)},${mrQuote(x.id)},${mrQuote(ref)})`,'text')])));
 let orders=table(['所属档案','订单编号','状态 / 客户类型','项目 / 客服','操作'],pair.flatMap(c=>(c.orders||[]).map(x=>[esc(c.name),esc(x.id),esc(x.status)+' / '+esc(x.customerType||c.customerType||'—'),esc(x.name||'—')+' / '+esc(x.consultant||'—'),btn('查看详情',`pcBusinessDetail('order',${mrQuote(c.id)},${mrQuote(x.id)},${mrQuote(ref)})`,'text')])));
 return contentModule('白条流水',white)+contentModule('售后 / 申述明细',tickets)+contentModule('订单详情',orders);
}
function pcBusinessDetail(kind,cid,id,ref=''){let c=pcData(cid,ref),key={white:'whiteEntries',ticket:'tickets',order:'orders'}[kind],x=kind==='white'?pcLedger(c||{}).find(x=>x.id===id):(c?.[key]||[]).find(x=>x.id===id);if(!x)return toast('这次快照未保存该条明细');let common={'客户档案':esc(c.name)+' · '+esc(cid),'记录编号':esc(x.id),'发生时间':esc(x.at||x.paidAt||'—'),'关联订单':esc(x.orderId||kind==='order'&&x.id||'—')},fields=kind==='order'?{'项目':esc(x.name||'—'),'订单状态':esc(x.status),'客户类型':esc(x.customerType||c.customerType||'—'),'归属客服':esc(x.consultant||'—'),'所属门店':esc(x.store||c.store||'—'),'订单金额':money(x.amount||0),'预约金':money(x.deposit||0),'排课时间':esc(x.scheduledAt||'未排课'),'合并流退':esc(x.mergeReturnType||'无'),'关联合并记录':esc(x.mergeRecordId||ref||'—')}:kind==='white'?{'业务类型':esc(x.type),'金额':cxSign(pcPaymentAmount(x)),'原始凭证':esc(x.originalId||'—')}: {'工单类型':esc(x.type||'售后'),'当前状态':esc(x.status||'—'),'问题摘要':esc(x.name||x.summary||'—'),'处理人':esc(x.handler||'—'),'处理记录':esc((x.logs||[]).map(l=>l.content||l.note||l).join('；')||'该快照未保存处理过程')};modal(kind==='order'?'订单详情':kind==='white'?'白条流水详情':'售后 / 申述详情',body(kv({...common,...fields})),(pcModalCustomer?btn('返回客户档案','pcCustomerModal()'):'')+btn('关闭','closeModal()'),true)}
function pcStatsTable(customers,title='统计重算结果'){let fields=[['总消费金额','totalConsumption','money'],['到店次数','visitCount','count'],['客单价','averageSpend','money'],['白条余额','whiteBalance','money'],['加微数','wechatCount','count'],['订单数','orderCount','count'],['最近到店时间','lastVisitAt',''],['最近消费时间','lastSpendAt',''],['客户类型','customerType','']],stats=customers.map(pcStats);return contentModule(title,table(['统计字段',...customers.map(c=>esc(c.name)+'<div class="tiny muted">'+esc(c.id)+'</div>')],fields.map(([label,k,format])=>[label,...stats.map(x=>format==='money'?money(x[k]):k==='visitCount'&&!x.hasVisitDetail?'未保存签到明细':k==='averageSpend'&&!x.hasVisitDetail?'—':esc(x[k]===0?0:x[k]||'—'))]))) }
function pcMergeEvidence(r){let after=r.snapshot.after,checks=r.reconciliation||pcReconciliation(r.snapshot.before,after),isNew=r.evidenceVersion===1;return contentModule(isNew?'迁移完整性结果':'按已保存快照核对',table(['核对项','合并前应有值','合并后值','结果'],checks.map(x=>[esc(x.label),x.expected===null?'未保存明细':esc(x.expected),esc(x.actual),badge(x.status,x.ok?'green':'orange')]))+body(!isNew?'<p class="small muted">历史记录未保存执行时的核对报告，此处按原快照重新对照；未改写历史快照。</p>':''))+pcStatsTable([after])+pcMigrationTable(r)+pcPeopleImpact(r)+pcTraceTable(r)}
function pcMigrationTable(r){let after=r.snapshot.after,rows=[];for(let [key,label] of [['orders','订单'],['payments','支付流水'],['whiteEntries','白条流水'],['wechat','加微记录'],['tickets','售后 / 申述'],['projects','项目'],['calls','通话'],['images','影像'],['checkins','签到'],['adjustments','手工调账']])for(let [i,x] of (after[key]||[]).entries())rows.push([label,esc(x.id||x.by||i+1),esc(x.sourceName||x.sourceCustomerId||x.sourceOrigin||x.origin||'历史快照未保存'),'并入 '+esc(after.id),esc(r.projectReviews?.[x.duplicateGroup]||x.mark||x.orderStateLabel||x.mergeReturnType||x.duplicateStatus||'保留原记录'),key==='projects'&&x.duplicateGroup?select(['待核实','分别保留','已确认重复（保留原记录）'],r.projectReviews?.[x.duplicateGroup]||'待核实',`aria-label="外协重复核对结论" onchange="pcProjectReview(${esc(mrQuote(r.id))},${esc(mrQuote(x.duplicateGroup))},this.value)"`):'—']);for(let key of ['tags','cultivationTags'])for(let tag of after[key]||[])rows.push([key==='tags'?'标签':'培养标签',esc(tag),r.pair.filter(c=>(c[key]||[]).includes(tag)).map(c=>esc(c.name)).join('、'),'并入 '+esc(after.id),'相同标签去重保留','—']);return contentModule('实际迁移条目',table(['数据类型','记录编号','来源档案','处理后归属','标记 / 处理结果','核对结论'],rows))}
function pcProjectReview(id,key,value){if(!PCCustomerStorage.locked)return customerWrite(()=>pcProjectReview(...arguments));let r=state.mergeRecords.find(r=>r.id===id);if(!r||!['待核实','分别保留','已确认重复（保留原记录）'].includes(value))return;r.projectReviews||={};r.projectReviews[key]=value;mrEvent(r,'外协项目核对：'+value+'；保留原项目记录');persist();if(pcRecordModalState?.id===id&&document.querySelector('#modal>[data-overlay-layer]:not(.is-closing)'))pcViewRecord(id,'changes');else render();toast('核对结论已保存')}
