function bpApprove(c){if(c.review&&c.review.status!=='approved')return;let p=c.businessPlan;c.approvedAt=now();c.approval=1;c.approvalResult=c.review?'已审核通过':'已通过（原型模拟）';c.approvedPlan=clone(c.submittedPlan);cxEvent(c,2,c.review?'完整业务及员工业绩方案审核通过，固定执行内容':'完整业务及员工业绩方案通过（原型模拟），固定执行内容','待审核','已通过');if(bpHasTarget(c)&&p.targetMode==='new'){c.newId=clNextId('ECF',pcCustomers());c.profileCreatedAt=now();c.createdProfile=bpFresh(c,c.newId);state.mergeCustomers.push(clone(c.createdProfile));cxEvent(c,3,'审核通过后创建空的分离档案','未创建',c.newId)}else{c.newId=bpHasTarget(c)?p.targetId:c.cus;c.profileCreatedAt='';cxEvent(c,3,bpHasTarget(c)?'使用经核实的已有目标档案':'本次不创建客户档案','',c.newId)}c.status='待执行';c.execution={attempts:0,status:'待执行'};c.step=5;c.planReady=true}
function bpResultUI(c){let r=c.bpResult;return contentModule('纠错调整单',body(kv({'调整单':'ADJ-'+c.id.slice(3),'关联工单':esc(c.id),'执行时间':esc(c.executedAt),'目标档案':bpHasTarget(c)?esc(bpTargetName(c))+' · '+esc(c.newId):'未创建新客户','确认状态':badge(c.status==='已完成'?'已完成':'待确认',c.status==='已完成'?'green':'orange')})),btn('查看原档案',`pcOpenCustomer(${mrQuote(c.cus)},'business')`)+(bpHasTarget(c)&&c.newId!==c.cus?btn('查看目标档案',`pcOpenCustomer(${mrQuote(c.newId)},'business')`):''))+bpCompare(c,r)+(c.replacementOrders?.length?contentModule('纠错补录订单',table(['新订单','原流退订单','项目','排客时间','状态'],c.replacementOrders.map(o=>[esc(o.id),esc(o.originalOrderId),esc(o.name),esc(o.scheduledAt||'暂不排客'),badge(o.status)]))):'')+contentModule('已执行业务明细',table(['记录','类型','处理前','处理后'],r.changes.map(x=>[esc(x.id),esc(BP_RECORD_LABELS[x.key]||x.key),esc(x.from),esc(x.to)])))+contentModule('资金归属审计链',table(['原交易 / 类型','原始金额','原档案调整','目标档案调整','实际支付动作'],r.financial.map(x=>[esc(x.original.id)+' · '+esc(x.original.type),cxSign(c.businessPlan.funds.find(f=>f.id===x.original.id).signed),cxSign(x.out.amount),cxSign(x.incoming.amount),'无新增收款、无再次退款'])))+bpStaffSummary(c,r)+bpStaffDetailTable(c)+contentModule('服务扣减纠正',table(['服务','原扣减资产','纠正方式','关联处理'],c.businessPlan.services.filter(s=>s.repair!=='none').map(s=>[esc(s.id),esc(s.record.assetId),s.repair==='replace'?'更正扣减来源':'恢复误扣并记待补收',esc(s.replacementAssetId||money(s.receivable))+'<div>'+esc(s.reason)+'</div>'])))+contentModule(c.status==='已完成'?'结果确认记录':'结果确认',body(c.status==='已完成'?kv({'确认人':esc(c.completedBy),'确认时间':esc(c.completedAt)}):field('核对结论（选填）',`<textarea aria-label="纠错结果核对结论" oninput="customerUpdateCase(&quot;financeOpinion&quot;,this.value)">${esc(c.financeOpinion||'')}</textarea>`)))}
function bpStaffDetailTable(c){return contentModule('按员工与门店拆分的调整明细',table(['关联订单 / 业绩类型','员工 / 门店','原业绩 → 纠正后','业绩变化','原提成 → 应计提成','提成变化','调整期'],c.businessPlan.staff.filter(bpStaffChanged).flatMap(r=>bpStaffLines(r).map(x=>[esc(r.record.orderId||r.id)+'<div class="tiny muted">'+esc(r.record.metric)+'</div>',esc(x.employee)+'<br>'+esc(x.store),x.before+' → '+x.after+' '+esc(r.record.unit||'元'),(x.amountDelta>0?'+':'')+x.amountDelta+' '+esc(r.record.unit||'元'),money(x.beforeCommission)+' → '+money(x.afterCommission),cxSign(x.commissionDelta),esc(r.adjustmentPeriod)]))))}
function ctTargetKind(c){return c.businessPlan?.targetMode==='existing'?'已有档案':'新档案'}
function ctTargetLabel(c){return ctTargetKind(c)+' · '+bpTargetName(c)}
function ctProfileText(profile){return [['name','姓名'],['phone','手机号'],['gender','性别'],['birthday','生日'],['remark','备注']].map(([k,t])=>t+'：'+esc(profile?.[k]||'未填写')).join('<br>')}
function ctReferenceText(c){let ids=c.businessPlan?.historyRefs||[];return ctHistory(c).filter(x=>ids.includes(x.id)).map(x=>esc(x.name)+' · '+esc(x.id)).join('<br>')||'未引用；按实际客户及当前业务人工核实'}
function bpRichProfile(c){return Array.isArray(c.assets)||Array.isArray(c.walletAccounts)||Array.isArray(c.performanceEntries)}
function bpCustomerOverview(c){let s=bpStats(c);return contentModule('业务与资金当前状态',body(kv({'当前净收款归属':money(s.receipts),'已记录服务消耗':s.hasServices?money(s.consumption):'未提供服务明细','账户总余额':money(s.balance),'其中冻结':s.hasWallet?money(s.frozen):'未提供冻结明细','待补收金额':money(s.receivable),'剩余权益':'按业务记录中的各项目分别核对'})))}
function bpCustomerBusiness(c){let wallets=c.walletAccounts||[],benefit=e=>e.beneficiaries||[{employee:e.employee,store:e.store,share:100,commission:e.commissionAmount}];return bpCustomerOverview(c)+contentModule('当前订单及业绩角色',table(['订单','项目 / 当前状态','各类业绩归属','操作'],(c.orders||[]).map(o=>[esc(o.id),esc(o.name)+'<div>'+badge(o.status)+'</div>',Object.entries(o.performanceOwners||{}).map(([metric,rows])=>esc(metric)+'：'+rows.map(x=>esc(x.employee)+' '+x.share+'%').join('、')).join('<br>')||'以原业务记录核实',btn('订单详情',`pcBusinessDetail('order',${mrQuote(c.id)},${mrQuote(o.id)})`,'text')])) )+contentModule('项目资产与剩余权益',table(['资产 / 来源','购买 / 赠送 / 转入','已用 / 已退 / 已失效','当前剩余 / 冻结','有效期'],(c.assets||[]).map(a=>[esc(a.name)+'<div class="tiny mono">'+esc(a.id)+'<br>来源：'+esc(a.sourceAssetId||a.orderId||'—')+'</div>',bpNum(a.purchased)+' / '+bpNum(a.gifted)+' / '+bpNum(a.transferredIn),bpNum(a.consumed)+' / '+bpNum(a.refunded)+' / '+bpNum(a.expired),bpNum(a.remaining)+' / '+bpNum(a.frozen)+' '+esc(a.unit||'次'),esc(a.expiresAt||'未提供')])) )+contentModule('本金与赠送账户',table(['账户','当前总余额','可用余额','冻结金额','历史失效'],wallets.map(a=>[esc(a.label),money(a.balance),money(bpNum(a.balance)-bpNum(a.frozen)),money(a.frozen),money(a.expired)])))+contentModule('账户流水与内部归属',table(['流水','业务 / 类型','金额','关联订单 / 原记录','发生时间'],pcLedger(c).map(f=>[esc(f.id),esc(f.type)+(f.isInternalAdjustment?'<div class="tiny muted">内部归属调整</div>':''),cxSign(pcPaymentAmount(f)),esc(f.orderId||f.originalId||'—'),esc(f.at||'—')])) )+contentModule('支付及归属调整',table(['原支付或调整','类型','金额','实际支付动作'],(c.payments||[]).map(f=>[esc(f.id),esc(f.type),cxSign(pcPaymentAmount(f)),'保留原始支付事实']).concat((c.paymentAllocations||[]).filter(f=>!f.accountId).map(f=>[esc(f.id),esc(f.kind)+' · '+esc(f.originalId),cxSign(f.amount),'无新增收退款'])))) +contentModule('服务与实际员工',table(['服务 / 订单','实际员工 / 门店','扣减来源 / 数量','结算状态'],(c.serviceRecords||[]).map(s=>[esc(s.name)+'<div class="tiny mono">'+esc(s.id)+' / '+esc(s.orderId)+'</div>',esc(s.employee)+' / '+esc(s.store),esc(s.assetId||'无项目扣减')+' / '+bpNum(s.qty),esc(s.settlementStatus||'保留原业务状态')])))+contentModule('回访与后续任务',table(['任务','内容','状态','负责人','计划时间'],(c.followups||[]).map(f=>[esc(f.id),esc(f.name)+'<div class="small muted">'+esc(f.content||'')+'</div>',esc(f.status),esc(f.handler),esc(f.dueAt||'未记录')])))+contentModule('当前员工业绩分配',table(['业务 / 指标','业绩基数','员工 / 门店 / 比例','应计提成','历史已发'],(c.performanceEntries||[]).map(e=>[esc(e.orderId||e.fundId||e.id)+'<div>'+esc(e.metric)+'</div>',bpNum(e.amount)+' '+esc(e.unit||'元'),benefit(e).map(b=>esc(b.employee)+' / '+esc(b.store)+' / '+bpNum(b.share)+'%').join('<br>'),benefit(e).map(b=>esc(b.employee)+'：'+money(b.commission)).join('<br>'),money(e.paidAmount||0)])))+((c.receivables||[]).length?contentModule('纠错关联待补收',table(['记录','关联服务','待收金额','状态'],c.receivables.map(r=>[esc(r.id),esc(r.serviceId),money(r.amount),esc(r.status)]))):'')}
function bpCustomerCorrectionHistory(c){let cases=state.cases.filter(x=>x.businessVersion===5&&(x.cus===c.id||x.newId===c.id||(c.correctionHistory||[]).includes(x.id)));return cases.length?contentModule('业务与员工业绩纠错记录',table(['工单','处理范围','当前进度','时间','操作'],cases.map(x=>[esc(x.id),esc({split:'客户分离',partial:'选定业务纠正',performance:'员工业绩纠正',profile:'基本资料纠正'}[x.businessPlan.scope]),flowStatusBadge(x),esc(x.submittedAt||x.date),btn('查看工单',`pcGoCase(${mrQuote(x.id)})`,'text')]))):''}
function apStatus(o,kind){let r=o.review;if(r?.status==='rejected')return '已驳回';if(r?.status==='finance')return '待财务加签';if(r?.status==='pending')return '待审核';if(kind==='correction'&&o.resultData)return o.status==='已完成'?'已完成':'待调整单确认';if(kind==='merge'&&o.recordId)return '已合并';return o.status==='执行失败'?'执行失败':r?.status==='approved'?'系统执行中':o.status}
window.PCModules['customer-shared-ui']={};
